head.script:
// 비상연락망 명부 목록

scwin.inputSeq;
scwin.gMsgStr;
scwin.gType;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gSndloc = js_sndloc;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // PanelToGroupBox(panel_1);
        panel_1.hide();
        tbox_nmlist_seq.hide();
        $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", false);
        await scwin.setCode();
        await scwin.setHeader();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "비상연락망 " + scwin.gMsgStr));
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "비상연락망 " + scwin.gMsgStr));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_list.errorMsg) {
            await $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.dts_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    try {
        await $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.dts_list_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF35005.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "비상연락망", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35005.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        if (row >= 1) {
            if (colid === "UPDATE_YN") {
                scwin.gType = 'U'; // 수정
                const options = {
                    id: "ULDSTF35005_POP",
                    title: "비상연락망 수정",
                    type: "browserPopup",
                    width: "635px",
                    height: "270px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/dscltrend/ULDSTF35005_POP.gfm", options);
            } else if (colid === "DEL_YN") {
                scwin.gType = 'D'; // 삭제
                await scwin.approval(row, scwin.gType);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_new_onclick = async function() {
    try {
        scwin.gType = "N"; // 신규
        const options = {
            id: "ULDSTF35005_POP",
            title: "비상연락망 신규등록",
            type: "browserPopup",
            width: "650px",
            height: "270px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dscltrend/ULDSTF35005_POP.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005.btn_new_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description 송신처구분코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_delList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_delList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_delList.insertRow();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name approval
 * @description 삭제 처리
 * @param {Number} row 행 인덱스
 * @param {*} gType gType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approval = async function(row, gType) {
    if (scwin.gType === "D") {
        scwin.gMsgStr = "삭제";
    }
    const rtn = window.confirm('[' + scwin.gMsgStr + ']하시겠습니까?');
    if (rtn === 1) {
        dts_delList.setCellData(1, "NMLIST_SEQ", dts_list.getCellData(row, "NMLIST_SEQ"));
        dts_delList.setCellData(1, "CONTN_ID", scwin.gType);
        dts_delList.setCellData(1, "LST_ADJPRN_ID", scwin.gEmpNo);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/AtsContactInfo.do",
            ref : "dts_delList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 부서설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (scwin.gLdMktTp === "1" || scwin.gLdMktTp === "2") {
        // setObjectValue(rdo_MktTpCd, gLdMktTp);
        rdo_MktTpCd.setValue("9"); // 시장구분 안함
        rdo_SndLocTpCd.setValue(scwin.gSndloc);
    } else {
        panel_1.show("");
        rdo_MktTpCd.setValue("9");
        rdo_SndLocTpCd.setValue("AA");
        $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", true);
    }

    // 목록 조회
    await scwin.search();
};

/**
 * @method
 * @name setApplNo
 * @description set Appl No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setApplNo = function(obj) {
    scwin.inputSeq = dts_list.getCellData(Number(obj), "NMLIST_SEQ");
};
